worker: В папке projects/cardputer-gif-player создай PlatformIO проект для M5Cardputer.

Создай файлы:

1. platformio.ini:
```
[env:m5stack-cardputer]
platform = espressif32
board = m5stack-cardputer
framework = arduino
trackfloat_width = 80
board_build.arduino.memory_type = qio_opi
board_build.flash_mode = qio
monitor_speed = 115200
lib_deps = 
	M5Stack/M5Cardputer
	https://github.com/bitbank2/AnimatedGIF.git
```

2. src/main.cpp — минимальная заглушка:
```cpp
#include <M5Cardputer.h>
#include <SD.h>

void setup() {
    auto cfg = M5.config();
    M5Cardputer.begin(cfg);

    // SD карта на Cardputer: CS=GPIO_NUM_4, SPI
    SD.begin(GPIO_NUM_4, SPI, 25000000);

    M5Cardputer.Display.setTextColor(WHITE);
    M5Cardputer.Display.drawString("GIF Player Ready", 10, 10);
}

void loop() {
    delay(100);
}
```

3. include/.gitkeep (пустой файл)

Создай папку src/ и include/ при необходимости.

worker: Замени src/main.cpp в projects/cardputer-gif-player на полноценный GIF-плеер.

Требования:
1. При старте сканирует SD-карту (корень /), находит *.gif файлы
2. Показывает список файлов на экране (скроллинг если > 5)
3. Клавишами ENTER/UP/DOWN выбирать GIF
4. Открывает выбранный GIF и проигрывает его бесконечно
5. ESC — возврат к списку файлов
6. При ошибках — сообщение на экране и возврат в меню

Используй библиотеку AnimatedGIF (bitbank2). Её API:
- #include <AnimatedGIF.h>
- AnimatedGIF gif;
- gif.open(filename, GIF_ReadCB); — открыть файл
- gif.getCanvasWidth(), gif.getCanvasHeight()
- gif.playFrame(bool bSync, GIF_DrawCB, void *pUser); — проиграть 1 кадр
- gif.close();

SD карта на Cardputer:
- CS = GPIO_NUM_4
- SPI, 25MHz
- SD.begin(GPIO_NUM_4, SPI, 25000000)

Callback для чтения:
```cpp
void *GIF_ReadCB(GIF_FILE *f, uint32_t *pBytesRead, uint32_t nBytesToRead, void *pBuffer) {
    File *file = (File *)f;
    *pBytesRead = file->read((uint8_t *)pBuffer, nBytesToRead);
    return (void *)file;
}
```

Callback для отрисовки:
```cpp
void GIF_DrawCB(GIF_DRAW *pDraw) {
    M5Cardputer.Display.pushImage(...);
}
```

Бесконечный цикл: после проигрывания всех кадров сбросить gif и начать заново.

Клавиатура Cardputer: M5Cardputer.Keyboard.isChange() и M5Cardputer.Keyboard.key() → KeyValue.

Вот полный план main.cpp:

```cpp
#include <M5Cardputer.h>
#include <SD.h>
#include <AnimatedGIF.h>
#include <vector>
#include <string>

// Прототипы
void *GIF_ReadCB(GIF_FILE *f, uint32_t *pBytesRead, uint32_t nBytesToRead, void *pBuffer);
void GIF_DrawCB(GIF_DRAW *pDraw);

AnimatedGIF gif;
File currentGifFile;

// Список файлов
std::vector<std::string> fileList;
int selectedIndex = 0;
int scrollOffset = 0;
bool gifMode = false;

void scanFiles() {
    fileList.clear();
    File root = SD.open("/");
    File entry;
    while ((entry = root.openNextFile())) {
        String name = entry.name();
        if (name.endsWith(".gif") || name.endsWith(".GIF")) {
            fileList.push_back(std::string(name.c_str()));
        }
        entry.close();
    }
    root.close();
}

void drawMenu() {
    M5Cardputer.Display.fillScreen(BLACK);
    M5Cardputer.Display.setTextColor(WHITE);
    M5Cardputer.Display.setTextSize(1);

    int y = 2;
    int maxLines = M5Cardputer.Display.height() / 10;

    if (fileList.empty()) {
        M5Cardputer.Display.drawString("No GIF files found", 10, y);
        return;
    }

    for (int i = scrollOffset; i < (int)fileList.size() && i < scrollOffset + maxLines; i++) {
        if (i == selectedIndex) {
            M5Cardputer.Display.fillRect(0, y, M5Cardputer.Display.width(), 10, BLUE);
            M5Cardputer.Display.setTextColor(WHITE);
        } else {
            M5Cardputer.Display.setTextColor(WHITE);
        }
        M5Cardputer.Display.drawString(fileList[i].c_str(), 10, y);
        y += 10;
    }
}

void playGIF(const char *filename) {
    gifMode = true;

    currentGifFile = SD.open(filename, FILE_READ);
    if (!currentGifFile) {
        M5Cardputer.Display.fillScreen(BLACK);
        M5Cardputer.Display.drawString("Failed to open:", 10, 10);
        M5Cardputer.Display.drawString(filename, 10, 20);
        delay(2000);
        gifMode = false;
        return;
    }

    if (!gif.open(&currentGifFile, GIF_ReadCB)) {
        M5Cardputer.Display.fillScreen(BLACK);
        M5Cardputer.Display.drawString("Invalid GIF", 10, 10);
        currentGifFile.close();
        delay(2000);
        gifMode = false;
        return;
    }

    int w = gif.getCanvasWidth();
    int h = gif.getCanvasHeight();

    M5Cardputer.Display.fillScreen(BLACK);

    // Бесконечный цикл анимации
    bool exitFlag = false;
    while (!exitFlag) {
        // Проигрываем все кадры
        while (gif.playFrame(false, GIF_DrawCB, &M5Cardputer.Display)) {
            // Проверка клавиш
            if (M5Cardputer.Keyboard.isChange()) {
                auto key = M5Cardputer.Keyboard.key();
                if (key.event == KEY_TAPPED && key.keyCode == KEY_ESC) {
                    exitFlag = true;
                    break;
                }
            }
        }

        // Сброс для повторного воспроизведения
        gif.close();
        currentGifFile.close();
        currentGifFile = SD.open(filename, FILE_READ);
        if (!currentGifFile) break;
        if (!gif.open(&currentGifFile, GIF_ReadCB)) break;

        // После сброса задержка (необязательно)
        delay(100);
    }

    gif.close();
    currentGifFile.close();
    gifMode = false;
}

void setup() {
    auto cfg = M5.config();
    M5Cardputer.begin(cfg);

    // SD карта: CS=GPIO_NUM_4
    if (!SD.begin(GPIO_NUM_4, SPI, 25000000)) {
        M5Cardputer.Display.fillScreen(BLACK);
        M5Cardputer.Display.setTextColor(RED);
        M5Cardputer.Display.drawString("SD Card failed!", 10, 10);
        M5Cardputer.Display.drawString("Check SD card", 10, 25);
        while (1) delay(100);
    }

    scanFiles();
    selectedIndex = 0;
    scrollOffset = 0;
}

void loop() {
    if (gifMode) return; // Воспроизведение в playGIF()

    // Обработка клавиш в меню
    if (M5Cardputer.Keyboard.isChange()) {
        auto key = M5Cardputer.Keyboard.key();
        if (key.event == KEY_TAPPED) {
            switch (key.keyCode) {
                case KEY_DOWN:
                case 's':
                case 'S':
                    if (selectedIndex < (int)fileList.size() - 1) {
                        selectedIndex++;
                        int maxLines = M5Cardputer.Display.height() / 10;
                        if (selectedIndex >= scrollOffset + maxLines) {
                            scrollOffset = selectedIndex - maxLines + 1;
                        }
                    }
                    break;
                case KEY_UP:
                case 'w':
                case 'W':
                    if (selectedIndex > 0) {
                        selectedIndex--;
                        if (selectedIndex < scrollOffset) {
                            scrollOffset = selectedIndex;
                        }
                    }
                    break;
                case KEY_ENTER:
                case ' ':
                    if (!fileList.empty()) {
                        playGIF(fileList[selectedIndex].c_str());
                        // После возврата — обновить меню
                    }
                    break;
            }
        }
    }

    drawMenu();
    delay(50);
}

// Callback чтения GIF
void *GIF_ReadCB(GIF_FILE *f, uint32_t *pBytesRead, uint32_t nBytesToRead, void *pBuffer) {
    File *file = (File *)f;
    *pBytesRead = file->read((uint8_t *)pBuffer, nBytesToRead);
    return (void *)file;
}

// Callback отрисовки кадра
void GIF_DrawCB(GIF_DRAW *pDraw) {
    M5GFX &display = M5Cardputer.Display;
    uint16_t *palette;
    uint8_t *pixels;

    if (pDraw->bHasPalette) {
        palette = (uint16_t *)pDraw->pPalette;
    } else {
        palette = nullptr;
    }

    if (pDraw->y + pDraw->h <= display.height() && pDraw->x + pDraw->w <= display.width()) {
        // Если изображение помещается
        if (palette) {
            // Палитра — рисуем попиксельно
            for (int y = 0; y < pDraw->h; y++) {
                for (int x = 0; x < pDraw->w; x++) {
                    uint8_t idx = ((uint8_t *)pDraw->pPixels)[y * pDraw->iPixelSkip + x];
                    if (idx < pDraw->iPaletteSize) {
                        display.drawPixel(pDraw->x + x, pDraw->y + y, palette[idx]);
                    }
                }
            }
        } else {
            // RGB данные
            display.pushImage(pDraw->x, pDraw->y, pDraw->w, pDraw->h, (uint16_t *)pDraw->pPixels);
        }
    }
}
```

Напиши этот main.cpp ПОЛНОСТЬЮ без сокращений и комментариев "// ..." и "остальной код". Весь файл целиком.
